#include <list>
#include <string>
#include <vector>

template <class Iterator, class Predicate>
int count_matching(Iterator first, Iterator last, Predicate pred) {
    int found = 0;
    for (; first != last; ++first) {
        if (pred(*first)) ++found;
    }
    return found;
}
